import{_ as o,o as t,c as d,ag as i}from"./chunks/framework.BZohXCq9.js";const m=JSON.parse('{"title":"Admin Dashboard -> Booking Management (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/admin-dashboard/booking-management.md","filePath":"modules/admin-dashboard/booking-management.md"}'),a={name:"modules/admin-dashboard/booking-management.md"};function n(l,e,s,c,r,u){return t(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="admin-dashboard-booking-management-deep" tabindex="-1">Admin Dashboard -&gt; Booking Management (deep) <a class="header-anchor" href="#admin-dashboard-booking-management-deep" aria-label="Permalink to &quot;Admin Dashboard -&gt; Booking Management (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>admin-dashboard</code><br><strong>Feature:</strong> <code>booking-management</code><br><strong>Route:</strong> <code>/admin-dashboard/bookingManagement</code></p><p>This module shows all bookings across the platform and lets the admin inspect booking details, update slot status, and cancel bookings.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show all student bookings with student, instructor, payment, and slot details.</li><li>Let admins update a slot to <code>available</code>, <code>booked</code>, <code>completed</code>, <code>refund</code>, <code>cancelled</code>, or <code>missed</code>.</li><li>Let admins cancel a booking slot from the dashboard.</li><li>Keep instructor availability and booking notifications in sync.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/components/AdminComponents/StudentBookingTable.tsx</code></td><td>Main admin booking screen</td><td>Calls <code>GET_ALL_STUDENT_BOOKINGS</code>, <code>UPDATE_BOOKING_STATUS</code>, and <code>CANCEL_BOOKING_ADMIN</code>; contains local <code>StatusDropdown</code> and <code>ViewDetailsModal</code> helpers.</td></tr><tr><td><code>Frontend/src/graphql/Queries/AdminBookingShowcase.ts</code></td><td>Booking queries</td><td>Defines <code>GET_ALL_STUDENT_BOOKINGS</code> and <code>GET_INSTRUCTOR_BOOKINGS_BY_ID</code>.</td></tr><tr><td><code>Frontend/src/graphql/mutations/AdminBookingsShowcase.ts</code></td><td>Booking mutations</td><td>Defines <code>UPDATE_BOOKING_STATUS</code> and <code>CANCEL_BOOKING_ADMIN</code>.</td></tr><tr><td><code>Frontend/src/types/AdminBookingShowcase.ts</code></td><td>TS booking contracts</td><td>Shared booking input/output typing for the page.</td></tr><tr><td><code>Frontend/src/layouts/AdminLayout.tsx</code></td><td>Shared admin layout behavior</td><td>Uses <code>useBookingNotifications</code> and <code>initSocket</code>; shows unseen booking badge on this menu item and clears it when this route is opened.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="get-all-student-bookings" tabindex="-1"><code>GET_ALL_STUDENT_BOOKINGS</code> <a class="header-anchor" href="#get-all-student-bookings" aria-label="Permalink to &quot;`GET_ALL_STUDENT_BOOKINGS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/AdminBookingShowcase.ts</code></li><li>Query field: <code>getAllStudentBookings</code></li><li>Returns student, instructor, slot list, payment method, booking status, timestamps</li><li>Used by: <code>StudentBookingTable.tsx</code></li></ul><h3 id="update-booking-status" tabindex="-1"><code>UPDATE_BOOKING_STATUS</code> <a class="header-anchor" href="#update-booking-status" aria-label="Permalink to &quot;`UPDATE_BOOKING_STATUS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/AdminBookingsShowcase.ts</code></li><li>Mutation field: <code>updateBookingStatusAdmin(input: UpdateBookingStatusInputAdmin!)</code></li><li>Input: <code>bookingId</code>, <code>slotId</code>, <code>status</code></li><li>Used by: status change actions in <code>StudentBookingTable.tsx</code></li></ul><h3 id="cancel-booking-admin" tabindex="-1"><code>CANCEL_BOOKING_ADMIN</code> <a class="header-anchor" href="#cancel-booking-admin" aria-label="Permalink to &quot;`CANCEL_BOOKING_ADMIN`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/AdminBookingsShowcase.ts</code></li><li>Mutation field: <code>cancelBookingAdmin(input: CancelBookingAdminInputAdmin!)</code></li><li>Input: <code>bookingId</code>, <code>slotId</code>, <code>studentId</code>, optional <code>reason</code></li><li>Used by: cancel action in <code>StudentBookingTable.tsx</code></li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs/AdminBookingType.js</code></li><li>Main types: <ul><li><code>StudentBookingAdmin</code></li><li><code>BookingSlotAdmin</code></li><li><code>StudentAdmin</code></li><li><code>InstructorAdmin</code></li><li><code>PaymentMethodAdmin</code></li></ul></li><li>Enums: <ul><li><code>SlotStatusAdmin</code></li><li><code>BookingStatusAdmin</code></li><li><code>FeedbackStatusAdmin</code></li></ul></li><li>Query fields: <ul><li><code>getAllStudentBookings</code></li><li><code>getInstructorBookingsById(instructorId: ID!)</code></li></ul></li><li>Mutation fields: <ul><li><code>updateBookingStatusAdmin(input: UpdateBookingStatusInputAdmin!)</code></li><li><code>cancelBookingAdmin(input: CancelBookingAdminInputAdmin!)</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/AdminBookingType.resolver.js</code></li><li>Query resolvers: <ul><li><code>getAllStudentBookings</code><ul><li>Loads all bookings</li><li>Populates <code>studentId</code> and <code>instructorId</code></li><li>Sorts by <code>createdAt</code> descending</li></ul></li><li><code>getInstructorBookingsById</code><ul><li>Same shape, filtered by instructor</li></ul></li></ul></li><li>Mutation resolvers: <ul><li><code>updateBookingStatusAdmin</code><ul><li>Validates status</li><li>Loads target booking and slot</li><li>Prevents early completion in production by checking slot end time with <code>getSlotEndTimestampUtc</code></li><li>Updates slot status/booked flags</li><li>Sets <code>completionMarkedAt</code>, <code>payoutEligibleAt</code>, and <code>payoutStatus</code> when status becomes <code>completed</code></li><li>Recomputes booking-level status</li><li>Syncs the mirrored slot inside <code>teacherAvailabilityModel</code></li><li>Sends notification emails through <code>notifyBookingParties</code></li></ul></li><li><code>cancelBookingAdmin</code><ul><li>Cancels the slot from the admin side</li><li>Updates booking and availability records</li><li>Returns updated booking payload</li></ul></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Primary booking source</td></tr><tr><td><code>server/src/models/teacherAvailability.model.js</code></td><td>Keeps availability slots aligned with booking status</td></tr><tr><td><code>server/src/utils/slotTimezone.js</code></td><td>Prevents premature completion based on business timezone</td></tr><tr><td><code>server/src/utils/SendOtpEmail.js</code></td><td>Sends booking-related notifications</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Admin opens booking management.</li><li><code>GET_ALL_STUDENT_BOOKINGS</code> loads all bookings with populated student/instructor data.</li><li>Frontend renders rows/cards and opens a detail modal when requested.</li><li>Changing a slot status calls <code>UPDATE_BOOKING_STATUS</code>.</li><li>Backend updates the slot, booking aggregate status, payout-related fields, and mirrored instructor availability slot.</li><li>Cancel action calls <code>CANCEL_BOOKING_ADMIN</code> and backend applies cancellation changes.</li><li>Shared admin layout clears the unseen booking count when this route is visited.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li><code>StudentBookingTable.tsx</code> is the live route component; there is another similarly named admin page file in the repo, but the router points to the component under <code>AdminComponents</code>.</li><li>Status changes affect more than the booking document: availability, payout readiness, and notification emails are all part of this module.</li></ul>',25)])])}const g=o(a,[["render",n]]);export{m as __pageData,g as default};
